import 'package:flutter_test/flutter_test.dart';
import 'package:translation_api/src/service/transcription/transcription_impl.dart';
import 'package:translation_api/translation_api.dart';

void main() {
  late final ITranscriptionService transcriptionService;

  setUpAll(() {
    transcriptionService = TranscriptionService();
  });
  test("Transcription service returns a valid result", () async {
    final res = await transcriptionService.getTranscription(
      sourceLanguage: "bn",
      audioContent: "",
      samplingRate: 16000,
    );
    expect(res.output, isNotEmpty);
  });
}
